const src = $('Lấy web cần audit').item.json;
const r = $json;
const raw = r.data ?? r.body;
const html = typeof raw === 'string' ? raw : '';
const status = r.statusCode ?? null;
// Phân loại (audit kiểm tra TRANG CHỦ của tên miền, không phải link trang con trên Maps):
//   true  = web sống · false = chết thật (tên miền không còn, đang rao bán, lỗi SSL, server lỗi/không phản hồi)
//   null  = chưa rõ (web chặn truy cập tự động 401/403/429, hoặc trang dựng bằng JS gần như không có HTML) → KHÔNG tính là chết
const errMsg = r.error ? String(r.error.message || r.error.description || JSON.stringify(r.error)) : '';
const parked = /forsale|for sale|domain (?:is )?for sale|parkingcrew|sedoparking|bodis\.com|dan\.com\/buy|afternic/i.test(html);
let reachable, issue = null;
if (r.error) {
  reachable = false;
  issue = /ENOTFOUND|EAI_AGAIN|ENODATA/i.test(errMsg) ? 'dns' : /SSL|TLS|CERT|EPROTO/i.test(errMsg) ? 'ssl' : /timeout|ETIMEDOUT|ECONNRESET|ECONNREFUSED|EHOSTUNREACH/i.test(errMsg) ? 'timeout' : 'error';
} else if (parked) { reachable = false; issue = 'parked'; }
else if ([401, 403, 429].includes(status)) { reachable = null; issue = 'blocked'; }
else if (status !== null && status >= 500) { reachable = false; issue = 'server'; }
else if (status !== null && status < 400 && html.length > 200) { reachable = true; }
else if (status !== null && status < 400) { reachable = null; issue = 'js'; }
else { reachable = false; issue = 'http'; }

const uniq = a => [...new Set(a)];
const noScript = html.replace(/<script[\s\S]*?<\/script>/gi, ' ').replace(/<style[\s\S]*?<\/style>/gi, ' ');
const plain = noScript.replace(/<[^>]+>/g, ' ').replace(/&nbsp;/g, ' ');
const hrefs = (html.match(/href\s*=\s*["'][^"']+["']/gi) || []).map(h => h.replace(/^href\s*=\s*["']/i, '').slice(0, -1));

// Email: text + mailto:
const emails = uniq([
  ...(noScript.match(/[a-z0-9._%+-]+@[a-z0-9.-]+\.[a-z]{2,}/gi) || []),
  ...hrefs.filter(h => /^mailto:/i.test(h)).map(h => h.replace(/^mailto:/i, '').split('?')[0])
].map(e => e.toLowerCase())).slice(0, 10);

// SĐT VN: text + tel:
const phones = uniq([
  ...(plain.match(/(?:\+84|\b0)(?:[\s.\-]?\d){9,10}\b/g) || []),
  ...hrefs.filter(h => /^tel:/i.test(h)).map(h => h.replace(/^tel:/i, ''))
].map(p => p.replace(/[^\d+]/g, ''))).slice(0, 10);

const facebooks = uniq(hrefs.filter(u => /^https?:\/\/(www\.|m\.)?facebook\.com\/(?!sharer|share|plugins|dialog|tr\b)/i.test(u))).slice(0, 3);
const zalos = uniq(hrefs.filter(u => /^https?:\/\/zalo\.me\//i.test(u))).slice(0, 3);

// Năm copyright mới nhất
const yrs = [...plain.matchAll(/(?:©|&copy;|copyright)[^0-9]{0,40}((?:19|20)\d{2})(?:\s*[-–]\s*((?:19|20)\d{2}))?/gi)]
  .map(m => Number(m[2] || m[1])).filter(y => y <= new Date().getFullYear());

const cmsRules = [
  ['WordPress', /wp-content|wp-includes/i], ['Wix', /wix\.com|wixstatic/i],
  ['Haravan', /haravan/i], ['Sapo', /sapo\.vn|bizweb/i], ['LadiPage', /ladipage|ladicdn/i],
  ['Shopify', /cdn\.shopify/i], ['Joomla', /joomla/i], ['Blogspot', /blogger\.com|blogspot/i],
  ['Webflow', /webflow/i], ['Next.js', /__next/i], ['Nuxt', /__nuxt/i], ['Squarespace', /squarespace/i]
];
const cms = (cmsRules.find(([, re]) => re.test(html)) || [null])[0];
const title = ((html.match(/<title[^>]*>([\s\S]*?)<\/title>/i) || [])[1] || '').trim();

return { json: { id: src.id, website_url: src.website_url, audit: {
  reachable,
  status_code: status,
  has_ssl: reachable !== false ? r.has_ssl : (issue === 'ssl' ? false : null),
  is_mobile_friendly: reachable ? /<meta[^>]+name\s*=\s*["']viewport["']/i.test(html) : null,
  copyright_year: yrs.length ? Math.max(...yrs) : null,
  cms, page_title: title.slice(0, 300),
  error: issue ? `${issue}: ${errMsg || 'HTTP ' + status}`.slice(0, 500) : null,
  emails, phones, facebooks, zalos
} } };
